mapper.select:
SELECT
COALESCE(SUM(CASE WHEN a.tickek_state = 1 AND a.ticket_activity = 1 THEN 1 ELSE 0 END), 0) AS fullCount,
COALESCE(SUM(CASE
    WHEN (a.tickek_state = 1 AND a.ticket_activity = 0)
      OR (a.tickek_state = 0 AND a.ticket_activity = 1)
    THEN 1 ELSE 0
END), 0) AS partialCount,
COALESCE(SUM(CASE WHEN a.tickek_state = 0 AND a.ticket_activity = 0 THEN 1 ELSE 0 END), 0) AS notCount
FROM zlkj_danger_data_accept.all_access_status a
INNER JOIN zlkj_danger_data_accept.accept_company c ON a.company_code = c.code


        AND c.countycode = #{countycode}


        AND c.yq_type = #{yqType}


        AND c.parkcode = #{parkCode}


        AND c.code IN

            #{code}



        AND c.is_scqy = #{isScqy}

SELECT CASE t.ticket_status WHEN '0' THEN '未签发' WHEN '1' THEN '已签发' WHEN '3' THEN '已验收' WHEN '4' THEN '作废' WHEN '5' THEN '撤销' ELSE '未知' END as name, COUNT(*) as value FROM zlkj_danger_data_accept.accept_ticket_formal t LEFT JOIN zlkj_danger_data_accept.accept_company c ON t.company_code = c.code
t.deleted = 0
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.parkcode = #{parkCode}
AND t.company_code IN
#{code}
AND c.is_scqy = #{isScqy}
GROUP BY t.ticket_status

SELECT
COALESCE(z.zydl, '未分类') as name,
COUNT(*) as value
FROM zlkj_danger_data_accept.accept_ticket_formal t
LEFT JOIN zlkj_danger_data_accept.zylxflb z ON t.ticket_type = z.xlbm
LEFT JOIN zlkj_danger_data_accept.accept_company c ON t.company_code = c.code

    t.deleted = 0

        AND c.countycode = #{countycode}


        AND c.yq_type = #{yqType}


        AND c.parkcode = #{parkCode}


        AND t.company_code IN

            #{code}



        AND c.is_scqy = #{isScqy}


GROUP BY z.zydl
ORDER BY value DESC
